export function fontWidth(table, s) {
  let w = 0;
  for (const ch of s) { const g = table[ch] || table['?']; w += g[0]; }
  return w;
}

// Blit text at (x, baselineY) in colour c. g must expose blend(x,y,c,a).
export function drawFont(g, x, baselineY, table, s, c) {
  let cx = x;
  for (const ch of s) {
    const gl = table[ch] || table['?'];
    if (gl.length > 1) {
      const [adv, xoff, yoff, w, h, b64] = gl;
      const bytes = B64(b64);
      for (let row = 0; row < h; row++) {
        for (let col = 0; col < w; col++) {
          const a = bytes[row * w + col];
          if (a) g.blend(cx + xoff + col, baselineY + yoff + row, c, a);
        }
      }
    }
    cx += gl[0];
  }
  return cx;
}
